1	// Shared contract for the native Nxeon Calendar + Tasks (/dashboard/calendar).
2	// Backend (lib/calendar/*, lib/actions-calendar.ts) and UI build against these.
3	// Connects to the customer's SOGo CalDAV over the mail server, authenticating with
4	// the SAME per-user mailbox credential the mail client uses (reuse resolveMailbox
5	// from lib/mail/imap.ts). SOGo DAV base: https://10.20.0.10/SOGo/dav (cert is for
6	// mail.nxeon.cloud → set servername + rejectUnauthorized:false when connecting by IP).
7	
8	export const CALDAV_BASE = process.env.CALDAV_BASE_URL || "https://10.20.0.10/SOGo/dav";
9	export const CALDAV_TLS_SERVERNAME = "mail.nxeon.cloud";
10	
11	export type CalendarInfo = {
12	  id: string; // CalDAV collection url
13	  name: string;
14	  color?: string;
15	  readOnly: boolean;
16	};
17	
18	export type CalAttendee = { name?: string; email: string };
19	
20	export type CalEvent = {
21	  id: string; // event href (used for update/delete)
22	  uid: string; // iCal UID
23	  calendarId: string;
24	  title: string;
25	  description?: string;
26	  location?: string;
27	  start: string; // ISO
28	  end: string; // ISO
29	  allDay: boolean;
30	  attendees?: CalAttendee[];
31	};
32	
33	export type TaskItem = {
34	  id: string; // href
35	  uid: string;
36	  calendarId: string;
37	  title: string;
38	  notes?: string;
39	  due?: string; // ISO
40	  completed: boolean;
41	  priority?: number; // 0-9 (iCal PRIORITY)
42	};
43	
44	export type EventInput = {
45	  calendarId: string;
46	  title: string;
47	  start: string; // ISO
48	  end: string; // ISO
49	  allDay?: boolean;
50	  description?: string;
51	  location?: string;
52	  attendees?: CalAttendee[];
53	};
54	
55	export type TaskInput = {
56	  calendarId: string;
