3	@theme {
4	  --color-brand-50: #f2f0ff;
5	  --color-brand-100: #e4e0ff;
6	  --color-brand-200: #c9c2ff;
7	  --color-brand-300: #a89aff;
8	  --color-brand-400: #8a70fb;
9	  --color-brand-500: #6f47f5;
10	  --color-brand-600: #5f2ee8;
11	  --color-brand-700: #5124c4;
12	  --color-brand-800: #421fa0;
13	  --color-brand-900: #371d7f;
14	
15	  --color-navy-950: #060a14;
16	  --color-navy-900: #0a101f;
17	  --color-navy-850: #0d1526;
18	  --color-navy-800: #111a30;
19	  --color-navy-700: #1a2540;
20	  --color-navy-600: #253354;
21	
22	  --color-accent-blue: #3b82f6;
23	  --color-accent-cyan: #22d3ee;
24	
25	  --animate-fade-up: fade-up 0.4s ease-out both;
26	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
27	
28	  /* Showcase mock-screen animations (marketing product pages). All are opt-in
29	     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
30	     resting state (bars full, lines visible) with no motion. */
31	  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
32	  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
33	  --animate-eq: eq 1.7s ease-in-out infinite;
34	  --animate-blink: blink 1.1s steps(1) infinite;
35	  --animate-sweep: sweep 3.4s ease-in-out infinite;
36	  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
37	
38	  @keyframes fade-up {
39	    from { opacity: 0; transform: translateY(8px); }
40	    to { opacity: 1; transform: translateY(0); }
41	  }
42	  @keyframes pulse-dot {
43	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
44	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
45	  }
46	  /* One-shot bar grow (origin at the base). Resting state = full. */
47	  @keyframes grow-up {
48	    from { transform: scaleY(0.06); }
49	    to { transform: scaleY(1); }
50	  }
51	  /* One-shot progress/usage fill. Resting state = full width. */
52	  @keyframes grow-x {
53	    from { transform: scaleX(0); }
54	    to { transform: scaleX(1); }
55	  }
56	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
57	  @keyframes eq {
58	    0%, 100% { transform: scaleY(0.35); }
59	    50% { transform: scaleY(1); }
60	  }
61	  /* Terminal cursor blink. Resting state = visible. */
62	  @keyframes blink {
63	    0%, 49% { opacity: 1; }
64	    50%, 100% { opacity: 0; }
65	  }
66	  /* Soft light sweep across a chart/highlight. */
67	  @keyframes sweep {
68	    0% { transform: translateX(-120%); opacity: 0; }
69	    40%, 60% { opacity: 0.7; }
70	    100% { transform: translateX(320%); opacity: 0; }
71	  }
72	  /* Staggered line/row reveal. Resting state = visible. */
73	  @keyframes line-in {
74	    from { opacity: 0; transform: translateY(6px); }
75	    to { opacity: 1; transform: translateY(0); }
76	  }
77	}
