92	@layer components {
93	  /* Surfaces */
94	  .card {
95	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
96	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
97	  }
98	  .card-hover {
99	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
100	  }
101	  .glass {
102	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
103	  }
104	  .glow-brand {
105	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
106	  }
107	
108	  /* Typography */
109	  .grad-text {
110	    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
111	  }
112	  .page-title {
113	    @apply text-2xl font-bold tracking-tight;
114	  }
115	  .section-label {
116	    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
117	  }
118	
119	  /* Buttons */
120	  .btn-primary,
121	  .btn-secondary,
122	  .btn-danger,
123	  .btn-ghost {
124	    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
125	  }
126	  .btn-primary {
127	    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
128	    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
129	  }
130	  .btn-secondary {
131	    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
132	  }
133	  .btn-danger {
134	    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
135	  }
136	  .btn-ghost {
137	    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
138	  }
139	
140	  /* Forms */
141	  .input {
142	    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
