154	    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
155	  }
156	
157	  /* Tables */
158	  .table-shell {
159	    @apply w-full text-sm;
160	  }
161	  .table-shell thead th {
162	    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
163	  }
164	  .table-shell tbody tr {
