71	const statusColors: Record<string, { dot: string; text: string; pulse?: boolean }> = {
72	  RUNNING: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
73	  online: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
74	  STOPPED: { dot: "bg-slate-500", text: "text-slate-400" },
75	  PENDING: { dot: "bg-amber-400", text: "text-amber-400" },
76	  PROVISIONING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
77	  REINSTALLING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
78	  DELETING: { dot: "bg-red-400", text: "text-red-400", pulse: true },
79	  SUSPENDED: { dot: "bg-red-400", text: "text-red-400" },
80	  ERROR: { dot: "bg-red-400", text: "text-red-400" },
81	  QUEUED: { dot: "bg-amber-400", text: "text-amber-400" },
82	  DONE: { dot: "bg-emerald-400", text: "text-emerald-400" },
83	  FAILED: { dot: "bg-red-400", text: "text-red-400" },
84	  OPEN: { dot: "bg-amber-400", text: "text-amber-400" },
85	  ANSWERED: { dot: "bg-brand-300", text: "text-brand-300" },
86	  CUSTOMER_REPLY: { dot: "bg-amber-400", text: "text-amber-400" },
87	  CLOSED: { dot: "bg-slate-500", text: "text-slate-400" },
88	  // Block storage volumes (Volume.status) + business email (EmailSubscription.status).
89	  // PENDING / SUSPENDED / DELETING are already covered above and behave the same here.
90	  ACTIVE: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
91	  ATTACHED: { dot: "bg-emerald-400", text: "text-emerald-400" },
92	  DETACHED: { dot: "bg-slate-500", text: "text-slate-400" },
93	  CANCELLED: { dot: "bg-slate-500", text: "text-slate-400" },
94	};
