96	export function StatusDot({ status, label }: { status: string; label?: string }) {
97	  const s = statusColors[status] ?? statusColors.STOPPED;
98	  return (
99	    <span className={`inline-flex items-center gap-2 text-xs font-medium ${s.text}`}>
100	      <span className={`h-2 w-2 rounded-full ${s.dot} ${s.pulse ? "animate-pulse-dot" : ""}`} />
101	      {(label ?? status).toLowerCase().replace(/_/g, " ")}
102	    </span>
103	  );
104	}
