165	export function fmtBytes(b: number): string {
166	  if (!b || b <= 0) return "0 B";
167	  const units = ["B", "KB", "MB", "GB", "TB", "PB"];
168	  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), units.length - 1);
169	  return `${(b / 1024 ** i).toFixed(1)} ${units[i]}`;
170	}
171	
172	export function fmtMoney(cents: number): string {
173	  return `$${(cents / 100).toFixed(2)}`;
174	}
175	
176	export function timeAgo(d: Date): string {
177	  const s = Math.floor((Date.now() - d.getTime()) / 1000);
178	  if (s < 60) return `${s}s ago`;
179	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
180	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
181	  return `${Math.floor(s / 86400)}d ago`;
182	}
