115	/* Client-side category heuristics (Primary / Promotions / Social tabs)        */
116	/* -------------------------------------------------------------------------- */
117	
118	export type MailTab = "primary" | "promotions" | "social";
119	
120	const PROMO_RE = /(newsletter|deal|sale|% off|unsubscribe|promo|offer|coupon|discount|marketing|no-?reply|noreply|billing|receipt|invoice|order)/i;
121	const SOCIAL_DOMAINS = /(facebook|instagram|twitter|x\.com|linkedin|github|reddit|discord|slack|notifications?|youtube|tiktok|pinterest|medium)/i;
122	
123	export function categoryOf(from: MailAddress, subject: string): MailTab {
124	  const hay = `${from.address} ${from.name ?? ""} ${subject}`;
125	  if (SOCIAL_DOMAINS.test(from.address) || SOCIAL_DOMAINS.test(from.name ?? "")) return "social";
126	  if (PROMO_RE.test(hay)) return "promotions";
127	  return "primary";
128	}
