export function calColor(cal: CalendarInfo | undefined, index = 0): string {
  const c = cal?.color?.trim();
  if (c && /^#?[0-9a-fA-F]{3,8}$/.test(c)) return c.startsWith("#") ? c : `#${c}`;
  return CAL_PALETTE[index % CAL_PALETTE.length];
}

/** hex (#rgb / #rrggbb) → rgba() string. */
export function hexToRgba(hex: string, alpha: number): string {
  let h = hex.replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const int = parseInt(h.slice(0, 6), 16);
  if (Number.isNaN(int)) return `rgba(111,71,245,${alpha})`;
  const r = (int >> 16) & 255;
  const g = (int >> 8) & 255;
  const b = int & 255;
  return `rgba(${r},${g},${b},${alpha})`;
}

