/** Minute offset from midnight, clamped to the given day. */
export function minutesInto(d: Date, day: Date): number {
  const start = startOfDay(day).getTime();
  const mins = (d.getTime() - start) / 60_000;
  return Math.max(0, Math.min(24 * 60, mins));
}

/** Does an event (with ISO start/end) intersect the given local day? */
export function eventOnDay(startISO: string, endISO: string, day: Date): boolean {
  const s = new Date(startISO).getTime();
  const e = new Date(endISO).getTime();
  const ds = startOfDay(day).getTime();
  const de = ds + MS_DAY;
  return s < de && e > ds;
}

