"use client";

import { useState } from "react";
import {
  Icon,
  MONTHS,
  WEEKDAYS_NARROW,
  addMonths,
  isSameDay,
  isSameMonth,
  isToday,
  monthGrid,
} from "./util";

/** Compact month picker in the left rail. Clicking a day jumps the main view;
 *  its own month can be paged independently of the main cursor. */
export function MiniCalendar({
  cursor,
  selected,
  onPick,
  busyDays,
}: {
  cursor: Date;
  selected: Date;
  onPick: (d: Date) => void;
  busyDays?: Set<string>; // "yyyy-m-d" keys that have events
}) {
  const [view, setView] = useState(() => new Date(cursor.getFullYear(), cursor.getMonth(), 1));
  const days = monthGrid(view);

  return (
    <div>
      <div className="mb-2 flex items-center justify-between">
        <span className="text-sm font-semibold text-slate-100">
          {MONTHS[view.getMonth()]} {view.getFullYear()}
        </span>
        <div className="flex items-center gap-0.5">
          <button
            onClick={() => setView((v) => addMonths(v, -1))}
            className="btn-ghost rounded-lg p-1"
            aria-label="Previous month"
          >
            <Icon.chevronLeft size={15} />
          </button>
          <button
            onClick={() => setView((v) => addMonths(v, 1))}
            className="btn-ghost rounded-lg p-1"
            aria-label="Next month"
          >
            <Icon.chevronRight size={15} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-0.5 text-center">
        {WEEKDAYS_NARROW.map((d, i) => (
          <span key={i} className="py-1 text-[10px] font-semibold text-slate-600">
            {d}
          </span>
        ))}
        {days.map((d) => {
          const inMonth = isSameMonth(d, view);
          const sel = isSameDay(d, selected);
          const today = isToday(d);
          const busy = busyDays?.has(`${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`);
          return (
            <button
              key={d.toISOString()}
              onClick={() => onPick(d)}
              className={`relative flex h-7 items-center justify-center rounded-lg text-[12px] transition-colors ${
                sel
                  ? "bg-gradient-to-r from-accent-blue to-brand-500 font-semibold text-white"
                  : today
                    ? "font-semibold text-brand-300 hover:bg-white/[0.06]"
                    : inMonth
                      ? "text-slate-300 hover:bg-white/[0.06]"
                      : "text-slate-600 hover:bg-white/[0.04]"
              }`}
            >
              {d.getDate()}
              {busy && !sel && (
                <span className="absolute bottom-0.5 h-1 w-1 rounded-full bg-brand-400" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
