"use client";

import { useEffect, useMemo, useRef } from "react";
import type { CalEvent } from "@/lib/calendar/types";
import {
  HOUR_PX,
  fmtTime,
  hexToRgba,
  isToday,
  minutesInto,
  startOfDay,
  eventOnDay,
  WEEKDAYS_SHORT,
} from "./util";

type Positioned = { ev: CalEvent; top: number; height: number; lane: number; lanes: number };

/** Pack overlapping timed events into side-by-side lanes for one day column. */
function layoutDay(events: CalEvent[], day: Date): Positioned[] {
  const timed = events
    .filter((e) => !e.allDay && eventOnDay(e.start, e.end, day))
    .sort((a, b) => a.start.localeCompare(b.start));

  const out: Positioned[] = [];
  // Greedy grouping of mutually-overlapping events into clusters.
  let cluster: Positioned[] = [];
  let clusterEnd = 0;

  const flush = () => {
    const lanes = Math.max(1, ...cluster.map((c) => c.lane + 1));
    cluster.forEach((c) => (c.lanes = lanes));
    out.push(...cluster);
    cluster = [];
    clusterEnd = 0;
  };

  for (const ev of timed) {
    const top = minutesInto(new Date(ev.start), day);
    const bottom = minutesInto(new Date(ev.end), day);
    const height = Math.max(18, ((bottom - top) / 60) * HOUR_PX);
    const startPx = (top / 60) * HOUR_PX;

    if (cluster.length && top >= clusterEnd) flush();

    // Find the first free lane within the current cluster.
    const taken = new Set(cluster.filter((c) => minutesInto(new Date(c.ev.end), day) > top).map((c) => c.lane));
    let lane = 0;
    while (taken.has(lane)) lane++;

    cluster.push({ ev, top: startPx, height, lane, lanes: 1 });
    clusterEnd = Math.max(clusterEnd, bottom);
  }
  if (cluster.length) flush();
  return out;
}

/** Scrolling time grid. `days` has length 1 (Day view) or 7 (Week view). */
export function WeekView({
  days,
  events,
  colorFor,
  onCreateAt,
  onOpenEvent,
  onPickDay,
}: {
  days: Date[];
  events: CalEvent[];
  colorFor: (calendarId: string) => string;
  onCreateAt: (day: Date, hour: number) => void;
  onOpenEvent: (ev: CalEvent) => void;
  onPickDay: (day: Date) => void;
}) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const hours = useMemo(() => Array.from({ length: 24 }, (_, i) => i), []);

  // Scroll to ~8am on mount / view change so the workday is visible.
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 7.5 * HOUR_PX;
  }, [days.length, days[0]?.toDateString()]);

  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();

  const anyAllDay = events.some((e) => e.allDay && days.some((d) => eventOnDay(e.start, e.end, d)));

  return (
    <div className="flex h-full flex-col">
      {/* Day header row */}
      <div className="flex flex-none border-b border-white/[0.06] pr-[10px]">
        <div className="w-14 flex-none" />
        {days.map((day) => {
          const today = isToday(day);
          return (
            <button
              key={day.toISOString()}
              onClick={() => onPickDay(day)}
              className="flex flex-1 flex-col items-center gap-0.5 py-2 transition-colors hover:bg-white/[0.02]"
            >
              <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                {WEEKDAYS_SHORT[day.getDay()]}
              </span>
              <span
                className={`flex h-7 min-w-7 items-center justify-center rounded-full px-1 text-sm font-semibold ${
                  today ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-200"
                }`}
              >
                {day.getDate()}
              </span>
            </button>
          );
        })}
      </div>

      {/* All-day strip */}
      {anyAllDay && (
        <div className="flex flex-none border-b border-white/[0.06] pr-[10px]">
          <div className="flex w-14 flex-none items-center justify-end pr-2 text-[10px] font-medium uppercase text-slate-600">
            all-day
          </div>
          {days.map((day) => {
            const allDay = events.filter((e) => e.allDay && eventOnDay(e.start, e.end, day));
            return (
              <div key={day.toISOString()} className="min-w-0 flex-1 space-y-0.5 border-l border-white/[0.05] p-1">
                {allDay.map((ev) => {
                  const color = colorFor(ev.calendarId);
                  return (
                    <button
                      key={ev.id}
                      onClick={() => onOpenEvent(ev)}
                      title={ev.title}
                      className="block w-full truncate rounded-md px-1.5 py-0.5 text-left text-[11px] font-medium text-white transition-colors hover:brightness-110"
                      style={{ backgroundColor: hexToRgba(color, 0.9) }}
                    >
                      {ev.title || "(untitled)"}
                    </button>
                  );
                })}
              </div>
            );
          })}
        </div>
      )}

      {/* Scrolling time grid */}
      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto">
        <div className="flex" style={{ height: 24 * HOUR_PX }}>
          {/* Hour gutter */}
          <div className="w-14 flex-none">
            {hours.map((h) => (
              <div key={h} className="relative" style={{ height: HOUR_PX }}>
                <span className="absolute -top-2 right-2 text-[10px] font-medium tabular-nums text-slate-600">
                  {h === 0 ? "" : h < 12 ? `${h} AM` : h === 12 ? "12 PM" : `${h - 12} PM`}
                </span>
              </div>
            ))}
          </div>

          {/* Day columns */}
          {days.map((day) => {
            const positioned = layoutDay(events, day);
            const today = isToday(day);
            return (
              <div key={day.toISOString()} className="relative min-w-0 flex-1 border-l border-white/[0.05]">
                {/* Hour lines + click targets */}
                {hours.map((h) => (
                  <div
                    key={h}
                    onClick={() => onCreateAt(day, h)}
                    className="border-b border-white/[0.04] transition-colors hover:bg-white/[0.02]"
                    style={{ height: HOUR_PX }}
                  />
                ))}

                {/* Current-time indicator */}
                {today && (
                  <div
                    className="pointer-events-none absolute inset-x-0 z-20 flex items-center"
                    style={{ top: (nowMin / 60) * HOUR_PX }}
                  >
                    <span className="-ml-1 h-2 w-2 flex-none rounded-full bg-red-400" />
                    <span className="h-px flex-1 bg-red-400/70" />
                  </div>
                )}

                {/* Events */}
                {positioned.map(({ ev, top, height, lane, lanes }) => {
                  const color = colorFor(ev.calendarId);
                  const widthPct = 100 / lanes;
                  const short = height < 34;
                  return (
                    <button
                      key={ev.id}
                      onClick={(e) => {
                        e.stopPropagation();
                        onOpenEvent(ev);
                      }}
                      title={ev.title}
                      className="absolute z-10 overflow-hidden rounded-lg border-l-2 px-1.5 py-1 text-left leading-tight backdrop-blur-sm transition-all hover:z-30 hover:brightness-125"
                      style={{
                        top,
                        height,
                        left: `calc(${lane * widthPct}% + 2px)`,
                        width: `calc(${widthPct}% - 4px)`,
                        backgroundColor: hexToRgba(color, 0.2),
                        borderLeftColor: color,
                      }}
                    >
                      <div className={`truncate text-[11px] font-semibold text-slate-100 ${short ? "leading-none" : ""}`}>
                        {ev.title || "(untitled)"}
                      </div>
                      {!short && (
                        <div className="truncate text-[10px] tabular-nums text-slate-400">
                          {fmtTime(new Date(ev.start))} – {fmtTime(new Date(ev.end))}
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
