"use client";

import { useEffect, useState } from "react";
import type { CalendarInfo, EventInput } from "@/lib/calendar/types";
import {
  Icon,
  isoToDateInput,
  isoToLocalInput,
  localInputToIso,
  addDays,
  endOfDay,
  startOfDay,
} from "./util";

export type EventDraft = {
  id?: string; // set when editing an existing event
  calendarId: string;
  title: string;
  start: string; // ISO
  end: string; // ISO
  allDay: boolean;
  location: string;
  description: string;
};

export function EventModal({
  draft,
  calendars,
  colorFor,
  onClose,
  onSave,
  onDelete,
}: {
  draft: EventDraft;
  calendars: CalendarInfo[];
  colorFor: (calendarId: string) => string;
  onClose: () => void;
  onSave: (input: EventInput, id?: string) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
}) {
  const writable = calendars.filter((c) => !c.readOnly);
  const [calendarId, setCalendarId] = useState(draft.calendarId || writable[0]?.id || calendars[0]?.id || "");
  const [title, setTitle] = useState(draft.title);
  const [allDay, setAllDay] = useState(draft.allDay);
  const [start, setStart] = useState(draft.start);
  const [end, setEnd] = useState(draft.end);
  const [location, setLocation] = useState(draft.location);
  const [description, setDescription] = useState(draft.description);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [confirmDel, setConfirmDel] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const editing = !!draft.id;
  const activeCal = calendars.find((c) => c.id === calendarId);
  const readOnly = !!activeCal?.readOnly;

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !saving && !deleting) onClose();
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter" && !readOnly) void submit();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [title, start, end, allDay, location, description, calendarId, saving, deleting]);

  // Keep end >= start when start moves.
  const onStartChange = (iso: string) => {
    setStart(iso);
    if (new Date(iso).getTime() > new Date(end).getTime()) {
      setEnd(new Date(new Date(iso).getTime() + 60 * 60 * 1000).toISOString());
    }
  };

  async function submit() {
    if (saving || readOnly) return;
    if (!title.trim()) {
      setError("Give the event a title.");
      return;
    }
    if (new Date(end).getTime() < new Date(start).getTime()) {
      setError("End time can't be before the start.");
      return;
    }
    setError(null);
    setSaving(true);
    try {
      const s = allDay ? startOfDay(new Date(start)).toISOString() : start;
      const e = allDay ? endOfDay(new Date(end)).toISOString() : end;
      await onSave(
        {
          calendarId,
          title: title.trim(),
          start: s,
          end: e,
          allDay,
          location: location.trim() || undefined,
          description: description.trim() || undefined,
        },
        draft.id
      );
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't save the event.");
      setSaving(false);
    }
  }

  async function remove() {
    if (!draft.id || deleting) return;
    setDeleting(true);
    try {
      await onDelete(draft.id);
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Couldn't delete the event.");
      setDeleting(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
      role="dialog"
      aria-modal="true"
      aria-label={editing ? "Edit event" : "New event"}
      onClick={onClose}
    >
      <div
        className="glass flex max-h-[92vh] w-full max-w-lg flex-col overflow-hidden shadow-2xl animate-fade-up"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
            <span className="text-brand-300"><Icon.calendar size={16} /></span>
            {editing ? "Edit event" : "New event"}
          </h3>
          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={16} />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 space-y-4 overflow-y-auto p-5">
          {/* Title */}
          <input
            autoFocus={!editing}
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            disabled={readOnly}
            placeholder="Add title"
            className="w-full border-b border-white/10 bg-transparent pb-2 text-lg font-semibold text-slate-100 outline-none transition-colors placeholder:text-slate-600 focus:border-brand-400/60"
          />

          {/* All-day toggle */}
          <label className="flex cursor-pointer items-center justify-between">
            <span className="flex items-center gap-2 text-sm font-medium text-slate-300">
              <Icon.allDay size={16} className="text-slate-500" />
              All day
            </span>
            <button
              type="button"
              role="switch"
              aria-checked={allDay}
              disabled={readOnly}
              onClick={() => setAllDay((v) => !v)}
              className={`relative h-6 w-11 flex-none rounded-full transition-colors ${allDay ? "bg-brand-500" : "bg-white/10"}`}
            >
              <span className={`absolute top-0.5 h-5 w-5 rounded-full bg-white transition-transform ${allDay ? "translate-x-[22px]" : "translate-x-0.5"}`} />
            </button>
          </label>

          {/* Start / End */}
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div>
              <label className="label">Starts</label>
              {allDay ? (
                <input
                  type="date"
                  value={isoToDateInput(start)}
                  disabled={readOnly}
                  onChange={(e) => onStartChange(localInputToIso(e.target.value))}
                  className="input [color-scheme:dark]"
                />
              ) : (
                <input
                  type="datetime-local"
                  value={isoToLocalInput(start)}
                  disabled={readOnly}
                  onChange={(e) => onStartChange(localInputToIso(e.target.value))}
                  className="input [color-scheme:dark]"
                />
              )}
            </div>
            <div>
              <label className="label">Ends</label>
              {allDay ? (
                <input
                  type="date"
                  value={isoToDateInput(end)}
                  disabled={readOnly}
                  onChange={(e) => setEnd(localInputToIso(e.target.value))}
                  className="input [color-scheme:dark]"
                />
              ) : (
                <input
                  type="datetime-local"
                  value={isoToLocalInput(end)}
                  disabled={readOnly}
                  onChange={(e) => setEnd(localInputToIso(e.target.value))}
                  className="input [color-scheme:dark]"
                />
              )}
            </div>
          </div>

          {/* Calendar picker */}
          <div>
            <label className="label">Calendar</label>
            <div className="relative">
              <span
                className="pointer-events-none absolute left-3 top-1/2 h-3 w-3 -translate-y-1/2 rounded-full"
                style={{ backgroundColor: colorFor(calendarId) }}
              />
              <select
                value={calendarId}
                disabled={readOnly && editing}
                onChange={(e) => setCalendarId(e.target.value)}
                className="input appearance-none pl-8 [color-scheme:dark]"
              >
                {calendars.map((c) => (
                  <option key={c.id} value={c.id} disabled={c.readOnly}>
                    {c.name}{c.readOnly ? " (read-only)" : ""}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Location */}
          <div>
            <label className="label flex items-center gap-1.5"><Icon.mapPin size={13} /> Location</label>
            <input
              value={location}
              disabled={readOnly}
              onChange={(e) => setLocation(e.target.value)}
              placeholder="Add a place or link"
              className="input"
            />
          </div>

          {/* Description */}
          <div>
            <label className="label flex items-center gap-1.5"><Icon.text size={13} /> Description</label>
            <textarea
              value={description}
              disabled={readOnly}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Add notes, agenda, details…"
              className="input min-h-[5rem] resize-y"
            />
          </div>

          {readOnly && (
            <p className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
              This calendar is read-only. You can view but not change its events.
            </p>
          )}
          {error && (
            <p className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">{error}</p>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
          <div>
            {editing && !readOnly && (
              confirmDel ? (
                <div className="flex items-center gap-2 text-xs">
                  <span className="text-slate-400">Delete?</span>
                  <button onClick={remove} disabled={deleting} className="btn-danger px-2.5 py-1 text-xs">
                    {deleting ? "Deleting…" : "Yes, delete"}
                  </button>
                  <button onClick={() => setConfirmDel(false)} className="btn-ghost px-2 py-1 text-xs">Cancel</button>
                </div>
              ) : (
                <button onClick={() => setConfirmDel(true)} className="btn-ghost gap-1.5 px-2.5 py-1.5 text-xs text-red-300 hover:bg-red-500/10">
