              <TaskRow key={t.id} task={t} onToggle={onToggle} onDelete={onDelete} />
            ))}

            {open.length === 0 && done.length > 0 && (
              <p className="py-3 text-center text-xs text-slate-500">All done. Nice work.</p>
            )}

            {done.length > 0 && (
              <div className="pt-1">
                <button
                  onClick={() => setShowDone((v) => !v)}
                  className="flex w-full items-center gap-1.5 px-1 py-1 text-[11px] font-semibold uppercase tracking-wider text-slate-600 hover:text-slate-400"
                >
                  <span className={`transition-transform ${showDone ? "rotate-90" : ""}`}>
                    <Icon.chevronRight size={12} />
                  </span>
                  Completed ({done.length})
                </button>
                {showDone && done.map((t) => (
                  <TaskRow key={t.id} task={t} onToggle={onToggle} onDelete={onDelete} />
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

function TaskRow({
  task,
  onToggle,
  onDelete,
}: {
  task: TaskItem;
  onToggle: (id: string, completed: boolean) => void;
  onDelete: (id: string) => void;
}) {
  const overdue = !task.completed && isOverdue(task.due);
  return (
    <div className="group flex items-start gap-2 rounded-lg px-1 py-1.5 transition-colors hover:bg-white/[0.03]">
      <button
        onClick={() => onToggle(task.id, !task.completed)}
        aria-label={task.completed ? "Mark incomplete" : "Mark complete"}
        className={`mt-0.5 flex h-4 w-4 flex-none items-center justify-center rounded-[5px] border transition-colors ${
          task.completed
            ? "border-brand-500 bg-brand-500 text-white"
            : "border-white/20 text-transparent hover:border-brand-400"
        }`}
      >
        <Icon.check size={11} />
      </button>
      <div className="min-w-0 flex-1">
        <p className={`text-[13px] leading-snug ${task.completed ? "text-slate-600 line-through" : "text-slate-200"}`}>
          {task.title}
        </p>
        {task.due && (
          <p className={`mt-0.5 flex items-center gap-1 text-[11px] ${overdue ? "text-red-400" : "text-slate-500"}`}>
            <Icon.clock size={11} />
            {overdue ? "Overdue · " : ""}{fmtDueDate(task.due)}
          </p>
        )}
      </div>
      <button
        onClick={() => onDelete(task.id)}
        aria-label="Delete task"
        className="flex-none rounded-md p-1 text-slate-600 opacity-0 transition-all hover:bg-red-500/10 hover:text-red-300 group-hover:opacity-100"
      >
        <Icon.trash size={13} />
      </button>
    </div>
  );
}
